"""List helpers."""


def flatten(items):
    """Flatten nested lists into a flat list of leaves."""
    out = []
    for it in items:
        # BUG: only one level deep — a nested list inside `it` is left unflattened.
        if isinstance(it, list):
            out.extend(it)
        else:
            out.append(it)
    return out

